  );
  TestValidator.predicate(
    "in_stock=true has non-negative records",
    inStockResponse.pagination.records >= 0,
  );
  TestValidator.predicate(
    "in_stock=true has non-negative pages",
    inStockResponse.pagination.pages >= 0,
