        productId: productB.id,
        body: {
          page: 0,
          limit: 20,
        } satisfies IEcommerceMallProductSnapshot.IRequest,
      },
    );
  typia.assert(sellerBSnapshots);
  TestValidator.predicate(
    "seller B can access their own product snapshots",
    sellerBSnapshots.data.length >= 0,
  );
