/**
 * Test seller shipment retrieval.
 * 1. Register and authenticate a seller
 * 2. Retrieve a shipment belonging to the seller
 * 3. Validate shipment details including tracking information and order items
 */
export async function test_api_seller_shipment_retrieve_own_shipment(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register and authenticate seller
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerAuth = await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      shop_name: RandomGenerator.name(),
      shop_description: RandomGenerator.paragraph({ sentences: 2 }),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies IEcommerceMallSeller.IJoin,
  });
  typia.assert(sellerAuth);
  // 2. Create a new connection for authenticated seller API calls
  const authenticatedSellerConnection: api.IConnection = {
    host: connection.host,
    headers: { Authorization: sellerAuth.token.access },
  };
  // 3. Retrieve shipment - in a real scenario, this shipment would be created
  // by the seller through a separate endpoint. For this test, we use a random
  // shipment ID to test the retrieval functionality.
  const shipmentId = typia.random<string & tags.Format<"uuid">>();
  const shipment = await api.functional.ecommerceMall.seller.shipments.at(
    authenticatedSellerConnection,
    { shipmentId },
  );
  typia.assert(shipment);
  // 4. Validate shipment details
  TestValidator.equals("shipment ID matches", shipment.id, shipmentId);
  TestValidator.predicate(
    "tracking number exists",
    () => shipment.tracking_number.length > 0,
  );
  TestValidator.predicate(
    "carrier name exists",
    () => shipment.carrier_name.length > 0,
  );
  TestValidator.predicate(
    "shipped_at is valid date-time",
    () => typeof shipment.shipped_at === "string",
  );
  TestValidator.predicate(
    "seller ID matches authenticated seller",
    () => shipment.seller.id === sellerAuth.seller.id,
  );
  TestValidator.equals(
    "seller shop name matches",
    shipment.seller.shop_name,
    sellerAuth.seller.shop_name,
  );
  TestValidator.predicate("order items array exists", () =>
    Array.isArray(shipment.order_items),
  );
}

