  // 11. Seller rejects the cancellation request
  const rejectedRequest =
    await api.functional.ecommerceMall.seller.order_items.cancellation_requests.update(
      sellerConnection,
      {
        orderItemId: orderItemId,
        requestId: cancellationRequest.id,
        body: {
          status: "rejected",
        } satisfies IEcommerceMallOrderItemCancellationRequest.IUpdate,
      },
    );
  typia.assert(rejectedRequest);
  // 12. Administrator retrieves the rejected cancellation request
  const retrievedRequest =
    await api.functional.ecommerceMall.admin.order_items.cancellation_requests.at(
      adminConnection,
      {
        orderItemId: orderItemId,
        requestId: cancellationRequest.id,
      },
    );
  typia.assert(retrievedRequest);
  // 13. Validate the response
  TestValidator.equals(
    "status is rejected",
    retrievedRequest.status,
    "rejected",
  );
  TestValidator.predicate(
    "responded_at is populated",
    retrievedRequest.responded_at !== null,
  );
  TestValidator.equals(
    "order item status is paid",
    retrievedRequest.order_item.status,
    "paid",
  );
}

