import { authorize_admin_refresh } from "../../../authorize/authorize_admin_refresh";
import { authorize_customer_join } from "../../../authorize/authorize_customer_join";
import { authorize_customer_login } from "../../../authorize/authorize_customer_login";
import { authorize_customer_refresh } from "../../../authorize/authorize_customer_refresh";

export async function test_api_admin_update_customer_profile_success(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create and authenticate as administrator
  const adminConnection: api.IConnection = { host: connection.host };
  const adminEmail = typia.assert<string & tags.MinLength<1> & tags.MaxLength<255> & tags.Format<"email">>(typia.random<string & tags.Format<"email">>());
  const adminPassword = RandomGenerator.alphaNumeric(16);
  const adminAuth = await authorize_admin_join(adminConnection, {
    body: {
      email: adminEmail,
      password: adminPassword,
    } satisfies IEcommerceMallAdmin.IJoin,
  });
  typia.assert(adminAuth);
  // 2. Create customer account to update
  const customerConnection: api.IConnection = { host: connection.host };
  const customerEmail = typia.assert<string & tags.MinLength<1> & tags.MaxLength<255> & tags.Format<"email">>(typia.random<string & tags.Format<"email">>());
  const customerPassword = RandomGenerator.alphaNumeric(16);
  const initialDisplayName = RandomGenerator.name();
  const initialPhoneNumber = RandomGenerator.mobile();
  const customerAuth = await authorize_customer_join(customerConnection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      display_name: initialDisplayName,
      phone_number: initialPhoneNumber,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IEcommerceMallCustomer.IJoin,
  });
  typia.assert(customerAuth);
  // Store original customer data for validation
  const originalCustomerId = customerAuth.id;
  const originalEmail = customerAuth.email;
  const originalUpdatedAt = customerAuth.updated_at;
  // 3. Admin updates customer profile with new display_name and phone_number
  const newDisplayName = RandomGenerator.name(3);
  const newPhoneNumber = RandomGenerator.mobile("011");
  const updatedCustomer: IEcommerceMallCustomer =
    await api.functional.ecommerceMall.admin.customers.update(adminConnection, {
      customerId: originalCustomerId,
      body: {
        display_name: newDisplayName,
        phone_number: newPhoneNumber,
      } satisfies IEcommerceMallCustomer.IUpdate,
    });
  typia.assert(updatedCustomer);
  // 4. Validate all expected changes
  TestValidator.equals(
    "customer ID unchanged",
    updatedCustomer.id,
    originalCustomerId,
  );
  TestValidator.equals("email unchanged", updatedCustomer.email, originalEmail);
  TestValidator.equals(
    "display name updated",
    updatedCustomer.display_name,
    newDisplayName,
  );
  TestValidator.equals(
    "phone number updated",
    updatedCustomer.phone_number,
    newPhoneNumber,
  );
  TestValidator.predicate(
    "updated_at modified",
    updatedCustomer.updated_at !== originalUpdatedAt,
  );
  TestValidator.predicate(
    "account status active",
    updatedCustomer.account_status === "active",
  );
  TestValidator.predicate(
    "created_at preserved",
    updatedCustomer.created_at !== null,
  );
  TestValidator.predicate(
    "deleted_at is null",
    updatedCustomer.deleted_at === null,
  );
  // 5. Customer can view updated profile by logging in with original credentials
  const customerLogin = await authorize_customer_login(customerConnection, {
    body: {
      email: originalEmail,
      password: customerPassword,
    } satisfies IEcommerceMallCustomer.ILogin,
  });
  typia.assert(customerLogin);
  TestValidator.equals(
    "customer sees updated display name",
    customerLogin.display_name,
    newDisplayName,
  );
  TestValidator.equals(
    "customer sees updated phone number",
    customerLogin.phone_number,
    newPhoneNumber,
  );
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IEcommerceMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallAdmin";
import type { IEcommerceMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallCustomer";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_admin_join } from "../../../authorize/authorize_admin_join";
import { authorize_admin_login } from "../../../authorize/authorize_admin_login";
import { authorize_admin_refresh } from "../../../authorize/authorize_admin_refresh";
import { authorize_customer_join } from "../../../authorize/authorize_customer_join";
import { authorize_customer_login } from "../../../authorize/authorize_customer_login";
import { authorize_customer_refresh } from "../../../authorize/authorize_customer_refresh";

export async function test_api_admin_update_banned_customer_rejected(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin authentication
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {
    body: {
      email: typia.random<string & tags.MinLength<1> & tags.MaxLength<255> & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
    } satisfies IEcommerceMallAdmin.IJoin,
  });
  const adminLoginConnection: api.IConnection = { host: connection.host };
  await authorize_admin_login(adminLoginConnection, {
    body: {
      email: (adminConnection.headers?.Authorization as string)?.replace(
        "Bearer ",
        "",
      ) ?? "",
      password: RandomGenerator.alphaNumeric(16),
    } satisfies IEcommerceMallAdmin.ILogin,
  });
  // 2. Create customer account
  const customerJoinConnection: api.IConnection = { host: connection.host };
  const customerAuth = await authorize_customer_join(customerJoinConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IEcommerceMallCustomer.IJoin,
  });
  typia.assert(customerAuth);
  const customerId: string & tags.Format<"uuid"> = customerAuth.id;
  // 3. Ban the customer account
  const banConnection: api.IConnection = { host: connection.host };
  banConnection.headers = {
    Authorization: adminLoginConnection.headers?.Authorization ?? "",
  };
  const bannedCustomer = await api.functional.ecommerceMall.admin.customers.ban(
    banConnection,
    { customerId },
  );
  typia.assert(bannedCustomer);
  TestValidator.equals(
    "customer banned",
    bannedCustomer.account_status,
    "banned",
  );
  // 4. Attempt to update banned customer (should fail)
  const updateConnection: api.IConnection = { host: connection.host };
  updateConnection.headers = {
    Authorization: adminLoginConnection.headers?.Authorization ?? "",
  };
  await TestValidator.error("banned customer update rejected", async () => {
    await api.functional.ecommerceMall.admin.customers.update(
      updateConnection,
      {
        customerId,
        body: {
          display_name: RandomGenerator.name(),
          phone_number: RandomGenerator.mobile(),
        } satisfies IEcommerceMallCustomer.IUpdate,
      },
    );
  });
  // 5. Verify customer profile remains unchanged (still banned)
  const getCustomer = await api.functional.ecommerceMall.admin.customers.update(
    updateConnection,
    {
      customerId,
      body: {},
    },
  );
  typia.assert(getCustomer);
  TestValidator.equals(
    "customer still banned",
    getCustomer.account_status,
    "banned",
  );
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IEcommerceMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallAdmin";
import type { IEcommerceMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallCustomer";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_admin_join } from "../../../authorize/authorize_admin_join";
import { authorize_admin_login } from "../../../authorize/authorize_admin_login";
import { authorize_admin_refresh } from "../../../authorize/authorize_admin_refresh";
import { authorize_customer_join } from "../../../authorize/authorize_customer_join";
import { authorize_customer_login } from "../../../authorize/authorize_customer_login";
import { authorize_customer_refresh } from "../../../authorize/authorize_customer_refresh";

/**
 * Test administrator can update customer profile with partial field updates.
 *
 * This test validates that:
 * 1) Admin can authenticate successfully
 * 2) Admin can create/update customer with only display_name
 * 3) Admin can update customer with only phone_number
 * 4) Admin can update customer with both fields together
 * 5) System returns complete customer object after each update
 */
export async function test_api_admin_update_customer_with_valid_fields(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin authentication
  const adminConnection: api.IConnection = { host: connection.host };
  const adminAuth = await authorize_admin_join(adminConnection, {
    body: {
      email: typia.assert<string & tags.MinLength<1> & tags.MaxLength<255> & tags.Format<"email">>(
        typia.random<string & tags.Format<"email">>(),
      ),
      password: typia.assert<string & tags.MinLength<8> & tags.MaxLength<128>>(
        RandomGenerator.alphaNumeric(16),
      ),
    } satisfies IEcommerceMallAdmin.IJoin,
  });
  typia.assert(adminAuth);
  // 2. Create customer account to update
  const customerConnection: api.IConnection = { host: connection.host };
  const customerAuth = await authorize_customer_join(customerConnection, {
    body: {
      email: typia.assert<string & tags.MinLength<1> & tags.MaxLength<255> & tags.Format<"email">>(
        typia.random<string & tags.Format<"email">>(),
      ),
      password: typia.assert<string & tags.MinLength<8> & tags.MaxLength<128>>(
        RandomGenerator.alphaNumeric(16),
      ),
      display_name: null,
      phone_number: null,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: null,
    } satisfies IEcommerceMallCustomer.IJoin,
  });
  typia.assert(customerAuth);
  const customerId = customerAuth.id;
  // 3. Update only display_name field
  const updateDisplayName: IEcommerceMallCustomer =
    await api.functional.ecommerceMall.admin.customers.update(adminConnection, {
      customerId,
      body: {
        display_name: RandomGenerator.name(),
      } satisfies IEcommerceMallCustomer.IUpdate,
    });
  typia.assert(updateDisplayName);
  TestValidator.equals(
    "display_name updated",
    updateDisplayName.display_name !== null,
    true,
  );
  // 4. Update only phone_number field (display_name should remain unchanged)
  const oldDisplayName = updateDisplayName.display_name;
  const updatePhoneNumber: IEcommerceMallCustomer =
    await api.functional.ecommerceMall.admin.customers.update(adminConnection, {
      customerId,
      body: {
        phone_number: RandomGenerator.mobile(),
      } satisfies IEcommerceMallCustomer.IUpdate,
    });
  typia.assert(updatePhoneNumber);
  TestValidator.equals(
    "phone_number updated",
    updatePhoneNumber.phone_number !== null,
    true,
  );
  TestValidator.equals(
    "display_name unchanged",
    updatePhoneNumber.display_name,
    oldDisplayName,
  );
  // 5. Update both fields together
  const updateBoth: IEcommerceMallCustomer =
    await api.functional.ecommerceMall.admin.customers.update(adminConnection, {
      customerId,
      body: {
        display_name: RandomGenerator.name(),
        phone_number: RandomGenerator.mobile(),
      } satisfies IEcommerceMallCustomer.IUpdate,
    });
  typia.assert(updateBoth);
  TestValidator.notEquals(
    "display_name changed",
    updateBoth.display_name,
    oldDisplayName,
  );
  TestValidator.notEquals(
    "phone_number changed",
    updateBoth.phone_number,
    updatePhoneNumber.phone_number,
  );
}

