    customerConnection,
    {
      body: {
        query: RandomGenerator.alphabets(5),
        category_id: null,
        min_price: 0,
        max_price: 1000000,
        in_stock: null,
        seller_approval_status: null,
        sort_by: undefined,
        sort_order: undefined,
        page: undefined,
        limit: undefined,
      } satisfies IEcommerceMallSearch.IRequest,
