/**
 * Test that a product where all reviews have been deleted returns the same result as a product with no reviews.
 * When customers delete their reviews, those reviews should be excluded from the average rating calculation and review count.
 * Verify that average_rating is null, review_count is 0, and all rating distribution values are 0,
 * even though the product historically had reviews that were subsequently deleted.
 */
export async function test_api_product_review_summary_with_all_deleted_reviews(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin setup - create category
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_login(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
    } satisfies IEcommerceMallAdmin.ILogin,
  });
  const category = await generate_random_ecommerce_mall_admin_categories_create(
    adminConnection,
    {
      body: {
        name: RandomGenerator.name(2),
      } satisfies IEcommerceMallCategory.ICreate,
    },
  );
  typia.assert(category);
  // 2. Seller setup - create product
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      shop_name: RandomGenerator.name(2),
      href: "",
      referrer: "",
    } satisfies IEcommerceMallSeller.IJoin,
  });
  const product = await generate_random_ecommerce_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        name: RandomGenerator.name(3),
        description: RandomGenerator.paragraph({ sentences: 5 }),
        category_id: category.id,
        base_price: typia.random<
          number & tags.Type<"uint32"> & tags.Minimum<1000>
        >(),
      } satisfies IEcommerceMallProduct.ICreate,
    },
  );
  typia.assert(product);
  // 3. Customer setup - create reviews
  const customerConnection: api.IConnection = { host: connection.host };
  const customer = await authorize_customer_join(customerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      href: "",
      referrer: "",
    } satisfies IEcommerceMallCustomer.IJoin,
  });
  typia.assert(customer);
  // Create multiple reviews for the product
  const reviews: IEcommerceMallReview[] = [];
  await ArrayUtil.asyncRepeat(3, async () => {
    const review = await generate_random_ecommerce_mall_customer_reviews_create(
      customerConnection,
      {
        body: {
          order_item_id: typia.random<string & tags.Format<"uuid">>(),
          product_id: product.id,
          rating: typia.random<
            number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<5>
          >(),
        } satisfies IEcommerceMallReview.ICreate,
      },
    );
    typia.assert(review);
    reviews.push(review);
  });
  // 4. Delete all reviews
  await ArrayUtil.asyncForEach(reviews, async (review) => {
    await api.functional.ecommerceMall.customer.reviews.erase(
      customerConnection,
      {
        reviewId: review.id,
      },
    );
  });
  // 5. Verify review summary shows null/0 values
  const summary =
    await api.functional.ecommerceMall.products.reviews.summary.at(connection, {
      productId: product.id,
    });
  typia.assert(summary);
  TestValidator.equals("average rating is null", summary.average_rating, null);
  TestValidator.equals("review count is 0", summary.review_count, 0);
  TestValidator.equals(
    "1-star count is 0",
    summary.rating_distribution["1"],
    0,
  );
  TestValidator.equals(
