        reason: RandomGenerator.paragraph({ sentences: 3 }),
      } satisfies IEcommerceMallOrder.ICancel,
    },
  );
  typia.assert(cancelledOrder);
  // 11. Validate cancellation workflow
  // All order items should exist
  TestValidator.predicate(
    "order items exist",
    cancelledOrder.order_items.length > 0,
