import { MyGlobal } from "../MyGlobal";
import { EcommerceMallReviewCollector } from "../collectors/EcommerceMallReviewCollector";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";
import { EcommerceMallReviewTransformer } from "../transformers/EcommerceMallReviewTransformer";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function postEcommerceMallCustomerReviews(props: {
  customer: CustomerPayload;
  body: IEcommerceMallReview.ICreate;
}): Promise<IEcommerceMallReview> {
  // Verify order item exists, belongs to customer, and is delivered
  const orderItem = await MyGlobal.prisma.ecommerce_mall_order_items.findFirst({
    where: {
      id: props.body.order_item_id,
      order: {
        customer: {
          id: props.customer.id,
        },
      },
    },
    select: {
      id: true,
      status: true,
      ecommerce_mall_product_variant_id: true,
      productVariant: {
        select: {
          ecommerce_mall_product_id: true,
        },
      },
    },
  });
  if (!orderItem) {
    throw new HttpException(
      "Order item not found or does not belong to you",
      403,
    );
  }
  // Verify order item status is "delivered"
  if (orderItem.status !== "delivered") {
    throw new HttpException("Can only review delivered orders", 400);
  }
  // Verify product_id matches order item's product
  if (
    orderItem.productVariant?.ecommerce_mall_product_id !==
    props.body.product_id
  ) {
    throw new HttpException("Product ID does not match order item", 400);
  }
  // Verify product exists and is not deleted
  const product = await MyGlobal.prisma.ecommerce_mall_products.findUnique({
    where: {
      id: props.body.product_id,
      deleted_at: null,
    },
  });
  if (!product) {
    throw new HttpException("Product not found or has been deleted", 400);
  }
  // Check for duplicate review
  const existingReview =
    await MyGlobal.prisma.ecommerce_mall_reviews.findUnique({
      where: {
        order_item_id: props.body.order_item_id,
      },
    });
  if (existingReview) {
    throw new HttpException("You have already reviewed this order item", 409);
  }
  // Validate rating (1-5)
  if (props.body.rating < 1 || props.body.rating > 5) {
    throw new HttpException("Rating must be between 1 and 5", 400);
  }
  // Create review using collector
  const created = await MyGlobal.prisma.ecommerce_mall_reviews.create({
    data: await EcommerceMallReviewCollector.collect({
      body: props.body,
      customer: props.customer,
    }),
    ...EcommerceMallReviewTransformer.select(),
  });
  // Transform and return
  return await EcommerceMallReviewTransformer.transform(created);
}

import { IEcommerceMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallCategory";
import { IEcommerceMallSearch } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallSearch";
import { IEcommerceMallSearchResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallSearchResult";
import { IEcommerceMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallSeller";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IPageIEcommerceMallSearchResult } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIEcommerceMallSearchResult";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function patchEcommerceMallSearch(props: {
  body: IEcommerceMallSearch.IRequest;
}): Promise<IPageIEcommerceMallSearchResult.ISummary> {
  // Validate price range
  if (
    props.body.min_price !== undefined &&
    props.body.min_price !== null &&
    props.body.max_price !== undefined &&
    props.body.max_price !== null &&
    props.body.min_price > props.body.max_price
  ) {
    throw new HttpException("min_price cannot be greater than max_price", 400);
  }
  // Validate pagination
  const page = props.body.page ?? 1;
  const limit = props.body.limit ?? 20;
  const skip = (page - 1) * limit;
  if (page < 1) {
    throw new HttpException("page must be at least 1", 400);
  }
  if (limit < 1 || limit > 100) {
    throw new HttpException("limit must be between 1 and 100", 400);
  }
  const query = props.body.query;
  // Build product search filter
  const productWhere: Prisma.ecommerce_mall_productsWhereInput = {
    deleted_at: null,
    status: "active",
    AND: [
      {
        OR: [
          { name: { contains: query, mode: "insensitive" } },
          { description: { contains: query, mode: "insensitive" } },
        ],
      },
    ],
  };
  // Category filter for products
  if (props.body.category_id !== undefined && props.body.category_id !== null) {
    productWhere.category_id = props.body.category_id;
  }
  // Price filter for products
  if (props.body.min_price !== undefined && props.body.min_price !== null) {
    productWhere.base_price = { gte: props.body.min_price };
  }
  if (props.body.max_price !== undefined && props.body.max_price !== null) {
    if (productWhere.base_price) {
      const basePrice = productWhere.base_price as any;
      productWhere.base_price = {
        gte: basePrice.gte,
        lte: props.body.max_price,
      };
    } else {
      productWhere.base_price = { lte: props.body.max_price };
    }
  }
  // In-stock filter for products
  if (props.body.in_stock === true) {
    productWhere.variants = {
      some: {
        deleted_at: null,
        stock_quantity: { gt: 0 },
      },
    };
  }
  // Seller approval status filter for products
  if (
    props.body.seller_approval_status !== undefined &&
    props.body.seller_approval_status !== null
  ) {
    productWhere.seller = {
      approval_status: props.body.seller_approval_status,
      deleted_at: null,
    };
  }
  // Category search filter
  const categoryWhere: Prisma.ecommerce_mall_categoriesWhereInput = {
    deleted_at: null,
    name: { contains: query, mode: "insensitive" },
  };
  // Seller search filter
  const sellerWhere: Prisma.ecommerce_mall_sellersWhereInput = {
    deleted_at: null,
    shop_name: { contains: query, mode: "insensitive" },
  };
  if (
    props.body.seller_approval_status !== undefined &&
    props.body.seller_approval_status !== null
  ) {
    sellerWhere.approval_status = props.body.seller_approval_status;
  }
  // Build order by
  const orderBy: Prisma.ecommerce_mall_productsOrderByWithRelationInput =
    props.body.sort_by === "price"
      ? props.body.sort_order === "asc"
        ? { base_price: "asc" }
        : { base_price: "desc" }
      : props.body.sort_by === "created_at"
        ? props.body.sort_order === "asc"
          ? { created_at: "asc" }
          : { created_at: "desc" }
        : props.body.sort_by === "name"
          ? props.body.sort_order === "asc"
            ? { name: "asc" }
            : { name: "desc" }
          : { created_at: "desc" };
  // Fetch data
  const [
    products,
    categories,
    sellers,
    productCount,
    categoryCount,
    sellerCount,
  ] = await Promise.all([
    MyGlobal.prisma.ecommerce_mall_products.findMany({
      where: productWhere,
      orderBy,
      skip,
      take: limit,
      select: {
        id: true,
        name: true,
        description: true,
        status: true,
        base_price: true,
        created_at: true,
        deleted_at: true,
        category: {
          select: {
            id: true,
            name: true,
            description: true,
            created_at: true,
            deleted_at: true,
            parent: {
              select: {
                id: true,
                name: true,
                created_at: true,
                deleted_at: true,
                parent: {
                  select: {
                    id: true,
                    name: true,
                    created_at: true,
                    deleted_at: true,
                  },
                },
              },
            },
          },
        },
        seller: {
          select: {
            id: true,
            email: true,
            shop_name: true,
            shop_description: true,
            approval_status: true,
            rejection_reason: true,
            account_status: true,
            created_at: true,
            deleted_at: true,
          },
        },
        images: {
          where: { deleted_at: null },
          orderBy: { sort_order: "asc" },
          take: 1,
          select: { url: true },
        },
        variants: {
          where: { deleted_at: null },
          select: { stock_quantity: true },
        },
        reviews: {
          select: { rating: true },
        },
      },
    }),
    MyGlobal.prisma.ecommerce_mall_categories.findMany({
      where: categoryWhere,
      select: {
        id: true,
        name: true,
        description: true,
        created_at: true,
        deleted_at: true,
        parent: {
          select: {
            id: true,
            name: true,
            created_at: true,
            deleted_at: true,
            parent: {
              select: {
                id: true,
                name: true,
                created_at: true,
                deleted_at: true,
              },
            },
          },
        },
        products: {
          where: { deleted_at: null, status: "active" },
          select: { id: true },
        },
        subcategories: {
          where: { deleted_at: null },
          select: { id: true },
        },
      },
    }),
    MyGlobal.prisma.ecommerce_mall_sellers.findMany({
      where: sellerWhere,
      select: {
        id: true,
        email: true,
        shop_name: true,
        shop_description: true,
        approval_status: true,
        rejection_reason: true,
        account_status: true,
        created_at: true,
        products: {
          where: { deleted_at: null, status: "active" },
          select: { id: true },
        },
      },
    }),
    MyGlobal.prisma.ecommerce_mall_products.count({ where: productWhere }),
    MyGlobal.prisma.ecommerce_mall_categories.count({ where: categoryWhere }),
    MyGlobal.prisma.ecommerce_mall_sellers.count({ where: sellerWhere }),
  ]);
  // Helper to build category summary with parent
  const buildCategorySummary = (
    cat: any,
  ): IEcommerceMallCategory.ISummary | null => {
    if (!cat) return null;
    return {
      id: cat.id,
      name: cat.name,
      parent: buildCategorySummary(cat.parent),
      created_at: toISOStringSafe(cat.created_at),
      deleted_at: cat.deleted_at ? toISOStringSafe(cat.deleted_at) : null,
    } satisfies IEcommerceMallCategory.ISummary;
  };
  // Transform to search results
  const productResults = await ArrayUtil.asyncMap(products, async (product) =>
    typia.assert<
      IEcommerceMallSearchResult.ISummary & {
        type: "product";
      }
    >({
      type: "product",
      name: product.name,
      description: product.description ?? undefined,
      thumbnailUrl: product.images?.[0]?.url ?? "",
      basePrice: Number(product.base_price),
      seller: typia.assert<IEcommerceMallSeller.ISummary>({
        id: product.seller.id,
        email: product.seller.email,
        shop_name: product.seller.shop_name,
        shop_description: product.seller.shop_description ?? null,
        approval_status: typia.assert<"pending" | "approved" | "rejected">(
          product.seller.approval_status,
        ),
        rejection_reason: product.seller.rejection_reason ?? null,
        account_status: typia.assert<"active" | "suspended" | "banned">(
          product.seller.account_status,
        ),
        created_at: toISOStringSafe(product.seller.created_at),
      }),
      category: buildCategorySummary(product.category)!,
      averageRating: product.reviews?.length
        ? typia.assert<number & tags.Minimum<0> & tags.Maximum<5>>(
            product.reviews.reduce(
              (
                sum: number,
                r: {
                  rating: number;
                },
              ) => sum + r.rating,
              0,
            ) / product.reviews.length,
          )
        : null,
      reviewCount: product.reviews?.length ?? 0,
    }),
  );
  const categoryResults = categories.map((category) =>
    typia.assert<
      IEcommerceMallSearchResult.ISummary & {
        type: "category";
      }
    >({
      type: "category",
      name: category.name,
      description: category.description ?? null,
      productCount: category.products?.length ?? 0,
      hasSubcategories: !!category.subcategories?.length,
    }),
  );
  const sellerResults = sellers.map((seller) =>
    typia.assert<
      IEcommerceMallSearchResult.ISummary & {
        type: "seller";
      }
    >({
      type: "seller",
      shopName: seller.shop_name,
      shopDescription: seller.shop_description ?? null,
      approvalStatus: typia.assert<"pending" | "approved" | "rejected">(
        seller.approval_status,
      ),
      productCount: seller.products?.length ?? 0,
    }),
  );
  // Merge and paginate results
  const allResults = [...productResults, ...categoryResults, ...sellerResults];
  const totalRecords = productCount + categoryCount + sellerCount;
  const paginatedResults = allResults.slice(skip, skip + limit);
  return {
    data: paginatedResults,
    pagination: {
      current: page,
      limit,
      records: totalRecords,
      pages: totalRecords > 0 ? Math.ceil(totalRecords / limit) : 0,
    } satisfies IPage.IPagination,
  };
}

import { IEcommerceMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallCustomer";
import { IEcommerceMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallOrder";
import { IEcommerceMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallOrderItem";
import { IEcommerceMallProductVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallProductVariant";
import { IEcommerceMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallSeller";
import { IEcommerceMallShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallShipment";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { AdminPayload } from "../decorators/payload/AdminPayload";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function postEcommerceMallAdminOrdersOrderIdForceCancel(props: {
  admin: AdminPayload;
  orderId: string & tags.Format<"uuid">;
  body: IEcommerceMallOrder.IForceCancel;
}): Promise<IEcommerceMallOrder> {
  // Retrieve order with order items
  const order = await MyGlobal.prisma.ecommerce_mall_orders.findUnique({
    where: { id: props.orderId },
    select: {
      id: true,
      order_number: true,
      shipping_recipient_name: true,
      shipping_phone_number: true,
      shipping_street_address: true,
      shipping_city: true,
      shipping_state: true,
      shipping_postal_code: true,
      shipping_country: true,
      total_price: true,
      status: true,
      created_at: true,
      updated_at: true,
      deleted_at: true,
      customer: {
        select: {
          id: true,
          email: true,
          display_name: true,
          phone_number: true,
          account_status: true,
          created_at: true,
        },
      },
      orderItems: {
        select: {
          id: true,
          quantity: true,
          unit_price: true,
          status: true,
          created_at: true,
          updated_at: true,
          deleted_at: true,
          ecommerce_mall_product_variant_id: true,
          productVariant: {
            select: {
              id: true,
              sku_code: true,
              price: true,
              stock_quantity: true,
            },
          },
        },
      },
    },
  });
  if (order === null) {
    throw new HttpException("Order not found", 404);
  }
  // Check if order is already cancelled or refunded
  if (order.status === "cancelled" || order.status === "refunded") {
    throw new HttpException("Order is already cancelled or refunded", 409);
  }
  // Perform all operations in a transaction
  await MyGlobal.prisma.$transaction(async (tx) => {
    // Update all order items to cancelled status
    await tx.ecommerce_mall_order_items.updateMany({
      where: { ecommerce_mall_order_id: props.orderId },
      data: {
        status: "cancelled",
        updated_at: new Date(),
      },
    });
    // Create snapshots and inventory records for each order item
    for (const item of order.orderItems) {
      // Create snapshot
      await tx.ecommerce_mall_order_item_snapshots.create({
        data: {
          id: v4(),
          order_item_id: item.id,
          changed_by_id: props.admin.id,
          snapshot_type: "cancellation",
          created_at: new Date(),
          previous_values: JSON.stringify({
            status: item.status,
            quantity: item.quantity,
            unit_price: item.unit_price,
          }),
          current_values: JSON.stringify({
            status: "cancelled",
            quantity: item.quantity,
            unit_price: item.unit_price,
          }),
        },
      });
      // Create inventory record for stock restoration
      const variant =
        await tx.ecommerce_mall_product_variants.findUniqueOrThrow({
          where: { id: item.ecommerce_mall_product_variant_id },
        });
      const newStock = variant.stock_quantity + item.quantity;
      await tx.ecommerce_mall_inventory_records.create({
        data: {
          id: v4(),
          ecommerce_mall_product_variant_id:
            item.ecommerce_mall_product_variant_id,
          quantity_change: item.quantity,
          reason: "admin_force_cancel",
          recorded_at: new Date(),
          current_stock: newStock,
          created_at: new Date(),
          updated_at: new Date(),
          deleted_at: null,
        },
      });
      // Update variant stock quantity
      await tx.ecommerce_mall_product_variants.update({
        where: { id: item.ecommerce_mall_product_variant_id },
        data: { stock_quantity: newStock },
      });
    }
    // Update order status to cancelled
    await tx.ecommerce_mall_orders.update({
      where: { id: props.orderId },
      data: {
        status: "cancelled",
        updated_at: new Date(),
      },
    });
  });
  // Retrieve updated order with all relations
  const updatedOrder =
    await MyGlobal.prisma.ecommerce_mall_orders.findUniqueOrThrow({
      where: { id: props.orderId },
      select: {
        id: true,
        order_number: true,
        shipping_recipient_name: true,
        shipping_phone_number: true,
        shipping_street_address: true,
        shipping_city: true,
        shipping_state: true,
        shipping_postal_code: true,
        shipping_country: true,
        total_price: true,
        status: true,
        created_at: true,
        updated_at: true,
        deleted_at: true,
        customer: {
          select: {
            id: true,
            email: true,
            display_name: true,
            phone_number: true,
            account_status: true,
            created_at: true,
          },
        },
        orderItems: {
          select: {
            id: true,
            quantity: true,
            unit_price: true,
            status: true,
            created_at: true,
            updated_at: true,
            deleted_at: true,
            ecommerce_mall_product_variant_id: true,
            productVariant: {
              select: {
                id: true,
                sku_code: true,
                price: true,
                stock_quantity: true,
              },
            },
          },
        },
      },
    });
  // Transform to response DTO
  return {
    id: updatedOrder.id,
    order_number: updatedOrder.order_number,
    shipping_recipient_name: updatedOrder.shipping_recipient_name,
    shipping_phone_number: updatedOrder.shipping_phone_number,
    shipping_street_address: updatedOrder.shipping_street_address,
    shipping_city: updatedOrder.shipping_city,
    shipping_state: updatedOrder.shipping_state,
    shipping_postal_code: updatedOrder.shipping_postal_code,
    shipping_country: updatedOrder.shipping_country,
