import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { AdminPayload } from "../decorators/payload/AdminPayload";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function deleteEcommerceMallAdminCategoriesCategoryId(props: {
  admin: AdminPayload;
  categoryId: string & tags.Format<"uuid">;
}): Promise<void> {
  // 1. Verify category exists and is not already deleted
  const category =
    await MyGlobal.prisma.ecommerce_mall_categories.findUniqueOrThrow({
      where: { id: props.categoryId, deleted_at: null },
      select: {
        id: true,
        name: true,
        description: true,
        parent_id: true,
        created_at: true,
        updated_at: true,
        deleted_at: true,
      },
    });
  // 2. Check for subcategories - prevent deletion if any exist
  const subcategoryCount =
    await MyGlobal.prisma.ecommerce_mall_categories.count({
      where: { parent_id: props.categoryId },
    });
  if (subcategoryCount > 0) {
    throw new HttpException(
      "Cannot delete category with subcategories. Delete or reassign subcategories first.",
      400,
    );
  }
  // 3. Get all products in this category to uncategorize them
  const products = await MyGlobal.prisma.ecommerce_mall_products.findMany({
    where: { category_id: props.categoryId },
    select: { id: true },
  });
  // 4. Create snapshot before deletion
  const snapshotId = v4() as string & tags.Format<"uuid">;
  const previousValues = JSON.stringify({
    id: category.id,
    name: category.name,
    description: category.description,
    parent_id: category.parent_id,
    created_at: toISOStringSafe(category.created_at),
    updated_at: toISOStringSafe(category.updated_at),
    deleted_at: category.deleted_at
      ? toISOStringSafe(category.deleted_at)
      : null,
  });
  const currentValues = JSON.stringify({
    id: category.id,
    name: category.name,
    description: category.description,
    parent_id: category.parent_id,
    created_at: toISOStringSafe(category.created_at),
    updated_at: toISOStringSafe(new Date()),
    deleted_at: toISOStringSafe(new Date()),
  });
  await MyGlobal.prisma.ecommerce_mall_category_snapshots.create({
    data: {
      id: snapshotId,
      category_id: props.categoryId,
      admin_id: props.admin.id,
      previous_values: previousValues,
      current_values: currentValues,
      created_at: new Date(),
      updated_at: new Date(),
      deleted_at: null,
    },
  });
  // 5. Update all products to uncategorized (set category_id to null)
  if (products.length > 0) {
    await MyGlobal.prisma.ecommerce_mall_products.updateMany({
      where: { category_id: props.categoryId },
      data: { category_id: { set: undefined } },
    });
  }
  // 6. Soft delete the category
  await MyGlobal.prisma.ecommerce_mall_categories.update({
    where: { id: props.categoryId },
    data: {
      deleted_at: new Date(),
      updated_at: new Date(),
    },
  });
}

import { IEcommerceMallInventoryRecord } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallInventoryRecord";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IPageIEcommerceMallInventoryRecord } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIEcommerceMallInventoryRecord";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { SellerPayload } from "../decorators/payload/SellerPayload";
import { EcommerceMallInventoryRecordAtSummaryTransformer } from "../transformers/EcommerceMallInventoryRecordAtSummaryTransformer";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function patchEcommerceMallSellerInventorySummary(props: {
  seller: SellerPayload;
  body: IEcommerceMallInventoryRecord.IRequest;
}): Promise<IPageIEcommerceMallInventoryRecord.ISummary> {
  const page = props.body.page ?? 1;
  const limit = props.body.limit ?? 20;
  const skip = (page - 1) * limit;
  const whereInput: Prisma.ecommerce_mall_inventory_recordsWhereInput = {
    AND: [
      {
        productVariant: {
          ecommerce_mall_product_id: {
            in: (
              await MyGlobal.prisma.ecommerce_mall_products.findMany({
                where: { seller_id: props.seller.id },
                select: { id: true },
              })
            ).map((p) => p.id),
          },
        },
      },
      ...(props.body.variant_id
        ? [
            {
              productVariant: {
                id: props.body.variant_id,
              },
            },
          ]
        : []),
      ...(props.body.product_id
        ? [
            {
              productVariant: {
                ecommerce_mall_product_id: props.body.product_id,
              },
            },
          ]
        : []),
      ...(props.body.recorded_at_from
        ? [
            {
              recorded_at: {
                gte: new Date(props.body.recorded_at_from),
              },
            },
          ]
        : []),
      ...(props.body.recorded_at_to
        ? [
            {
              recorded_at: {
                lte: new Date(props.body.recorded_at_to),
              },
            },
          ]
        : []),
      ...(props.body.reason ? [{ reason: props.body.reason }] : []),
    ],
  } satisfies Prisma.ecommerce_mall_inventory_recordsWhereInput;
  const orderByInput: Prisma.ecommerce_mall_inventory_recordsOrderByWithRelationInput =
    props.body.sort_by === "quantity_change"
      ? { quantity_change: props.body.sort_order ?? "desc" }
      : props.body.sort_by === "reason"
        ? { reason: props.body.sort_order ?? "desc" }
        : { recorded_at: props.body.sort_order ?? "desc" };
  const [data, total] = await Promise.all([
    MyGlobal.prisma.ecommerce_mall_inventory_records.findMany({
      where: whereInput,
      skip,
      take: limit,
      orderBy: orderByInput,
      ...EcommerceMallInventoryRecordAtSummaryTransformer.select(),
    }),
    MyGlobal.prisma.ecommerce_mall_inventory_records.count({
      where: whereInput,
    }),
  ]);
  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    } satisfies IPage.IPagination,
    data: await ArrayUtil.asyncMap(
      data,
      EcommerceMallInventoryRecordAtSummaryTransformer.transform,
    ),
  } satisfies IPageIEcommerceMallInventoryRecord.ISummary;
}

import { IEcommerceMallCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallCartItem";
import { IEcommerceMallProductVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallProductVariant";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function postEcommerceMallCustomerCartItems(props: {
  customer: CustomerPayload;
  body: IEcommerceMallCartItem.ICreate;
}): Promise<IEcommerceMallCartItem> {
  // Validate product variant exists and is not deleted
  const variant =
    await MyGlobal.prisma.ecommerce_mall_product_variants.findFirst({
      where: {
        id: props.body.product_variant_id,
        deleted_at: null,
      },
      include: {
        product: {
          select: {
            base_price: true,
          },
        },
        variantOptions: {
          select: {
            key: true,
            value: true,
          },
        },
      },
    });
  if (variant === null) {
    throw new HttpException("Product variant not found", 404);
  }
  // Validate stock quantity
  if (props.body.quantity > variant.stock_quantity) {
    throw new HttpException(
      `Insufficient stock. Available: ${variant.stock_quantity}`,
      400,
    );
  }
  const now = new Date();
  const cartItemId: string = v4();
  try {
    // Attempt to create new cart item
    const created = await MyGlobal.prisma.ecommerce_mall_cart_items.create({
      data: {
        id: cartItemId,
        customer: {
          connect: {
            id: props.customer.id,
          },
        },
        productVariant: {
          connect: {
            id: props.body.product_variant_id,
          },
        },
        quantity: props.body.quantity,
        is_available: true,
        added_at: now,
        created_at: now,
        updated_at: now,
        deleted_at: null,
      },
    });
    const unitPrice = variant.price ?? variant.product.base_price;
    const subtotal = created.quantity * unitPrice;
    return {
      items: [
        {
          id: created.id as string & tags.Format<"uuid">,
          quantity: created.quantity,
          is_available: created.is_available,
          added_at: toISOStringSafe(created.added_at) as string &
            tags.Format<"date-time">,
          product_variant: {
            id: variant.id as string & tags.Format<"uuid">,
            sku_code: variant.sku_code,
            price: variant.price ?? undefined,
            stock_quantity: variant.stock_quantity,
            option_values: Object.fromEntries(
              variant.variantOptions.map(
                (opt: { key: string; value: string }) => [opt.key, opt.value],
              ),
            ),
          } satisfies IEcommerceMallProductVariant.ISummary,
          subtotal: subtotal,
        } satisfies IEcommerceMallCartItem.ISummary,
      ],
      total: subtotal,
    } satisfies IEcommerceMallCartItem;
  } catch (error: any) {
    // Handle unique constraint violation - update existing cart item
    if (error.code === "P2002") {
      // Update quantity of existing cart item
      const updated = await MyGlobal.prisma.ecommerce_mall_cart_items.update({
        where: {
          customer_id_product_variant_id: {
            customer_id: props.customer.id,
            product_variant_id: props.body.product_variant_id,
          },
        },
        data: {
          quantity: props.body.quantity,
          updated_at: now,
        },
      });
      const unitPrice = variant.price ?? variant.product.base_price;
      const subtotal = updated.quantity * unitPrice;
      return {
        items: [
          {
            id: updated.id as string & tags.Format<"uuid">,
            quantity: updated.quantity,
            is_available: updated.is_available,
            added_at: toISOStringSafe(updated.added_at) as string &
              tags.Format<"date-time">,
            product_variant: {
              id: variant.id as string & tags.Format<"uuid">,
              sku_code: variant.sku_code,
              price: variant.price ?? undefined,
              stock_quantity: variant.stock_quantity,
              option_values: Object.fromEntries(
                variant.variantOptions.map(
                  (opt: { key: string; value: string }) => [opt.key, opt.value],
                ),
              ),
            } satisfies IEcommerceMallProductVariant.ISummary,
            subtotal: subtotal,
          } satisfies IEcommerceMallCartItem.ISummary,
        ],
        total: subtotal,
      } satisfies IEcommerceMallCartItem;
    }
    throw error;
  }
}

import { IEcommerceMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallCustomer";
import { IEcommerceMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallOrder";
import { IEcommerceMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallOrderItem";
import { IEcommerceMallOrderItemRefundRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallOrderItemRefundRequest";
import { IEcommerceMallProductVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallProductVariant";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { EcommerceMallOrderItemRefundRequestCollector } from "../collectors/EcommerceMallOrderItemRefundRequestCollector";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";
import { EcommerceMallOrderItemRefundRequestTransformer } from "../transformers/EcommerceMallOrderItemRefundRequestTransformer";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function postEcommerceMallCustomerOrderItemsOrderItemIdRefundRequests(props: {
  customer: CustomerPayload;
  orderItemId: string & tags.Format<"uuid">;
  body: IEcommerceMallOrderItemRefundRequest.ICreate;
}): Promise<IEcommerceMallOrderItemRefundRequest> {
  // 1. Validate order item exists
  const orderItem = await MyGlobal.prisma.ecommerce_mall_order_items.findFirst({
    where: {
      id: props.orderItemId,
      deleted_at: null,
    },
  });
  if (orderItem === null) {
    throw new HttpException("Order item not found", 404);
  }
  // 2. Verify the order belongs to the authenticated customer
  const order = await MyGlobal.prisma.ecommerce_mall_orders.findFirst({
    where: {
      id: orderItem.ecommerce_mall_order_id,
      ecommerce_mall_customer_id: props.customer.id,
      deleted_at: null,
    },
  });
  if (order === null) {
    throw new HttpException("Order item not found", 404);
  }
  // 3. Verify order item status is 'delivered'
  if (orderItem.status !== "delivered") {
    throw new HttpException(
      "Order item must be delivered to request refund",
      400,
    );
  }
  // 4. Calculate days since delivery and validate <= 7
  const daysSinceDelivery = Math.floor(
    (new Date().getTime() - new Date(orderItem.created_at).getTime()) /
      (1000 * 60 * 60 * 24),
  );
  if (daysSinceDelivery > 7) {
    throw new HttpException(
      "Refund request must be made within 7 days of delivery",
      400,
    );
  }
  // 5. Check no existing refund request exists
  const existingRequest =
    await MyGlobal.prisma.ecommerce_mall_order_item_refund_requests.findUnique({
      where: {
        ecommerce_mall_order_item_id: props.orderItemId,
      },
    });
  if (existingRequest !== null) {
    throw new HttpException(
      "Refund request already exists for this order item",
      409,
    );
  }
  // 6-7. Create refund request using collector
  const refundRequest =
    await MyGlobal.prisma.ecommerce_mall_order_item_refund_requests.create({
      data: await EcommerceMallOrderItemRefundRequestCollector.collect({
        body: props.body,
        ecommerceMallOrderItems: orderItem,
      }),
      ...EcommerceMallOrderItemRefundRequestTransformer.select(),
    });
  // 8. Transform and return
  return await EcommerceMallOrderItemRefundRequestTransformer.transform(
    refundRequest,
  );
}

import { IEcommerceMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallCustomer";
import { IEcommerceMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallOrder";
import { IEcommerceMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallOrderItem";
import { IEcommerceMallProductVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallProductVariant";
import { IEcommerceMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallSeller";
import { IEcommerceMallShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IEcommerceMallShipment";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function postEcommerceMallCustomerShipmentsShipmentIdConfirmDelivery(props: {
  customer: CustomerPayload;
  shipmentId: string & tags.Format<"uuid">;
}): Promise<IEcommerceMallShipment> {
  // 1. Validate shipment exists and is not soft-deleted
  const shipment = await MyGlobal.prisma.ecommerce_mall_shipments.findUnique({
    where: { id: props.shipmentId },
    select: {
      id: true,
      tracking_number: true,
      carrier_name: true,
      shipped_at: true,
      delivered_at: true,
      seller_id: true,
      created_at: true,
      updated_at: true,
      deleted_at: true,
      seller: {
        select: {
          id: true,
          email: true,
          shop_name: true,
          shop_description: true,
          approval_status: true,
          rejection_reason: true,
          account_status: true,
          created_at: true,
        },
      },
    },
  });
  if (shipment === null || shipment.deleted_at !== null) {
    throw new HttpException("Shipment not found", 404);
  }
  // 2. Verify shipment is not already delivered
  if (shipment.delivered_at !== null) {
    throw new HttpException("Shipment already delivered", 409);
  }
  // 3. Find all orders owned by this customer
  const customerOrders = await MyGlobal.prisma.ecommerce_mall_orders.findMany({
    where: {
      ecommerce_mall_customer_id: props.customer.id,
      deleted_at: null,
    },
    select: {
      id: true,
    },
  });
  if (customerOrders.length === 0) {
    throw new HttpException("No orders found for this customer", 403);
  }
  const customerOrderIds = customerOrders.map((order) => order.id);
  // 4. Find all order items from customer's orders with status='paid'
  // These are the items that would be in shipments the customer can confirm
  const orderItemsToUpdate =
    await MyGlobal.prisma.ecommerce_mall_order_items.findMany({
      where: {
        ecommerce_mall_order_id: {
          in: customerOrderIds,
        },
        status: "paid",
        deleted_at: null,
      },
      select: {
        id: true,
        ecommerce_mall_order_id: true,
        status: true,
      },
    });
  if (orderItemsToUpdate.length === 0) {
    throw new HttpException(
      "No payable order items found for this customer",
      400,
    );
  }
  // 5. Begin transaction to update shipment and order items
  const deliveredAt = new Date();
  await MyGlobal.prisma.$transaction(async (tx) => {
    // a) Update shipment.delivered_at
    await tx.ecommerce_mall_shipments.update({
      where: { id: props.shipmentId },
      data: {
        delivered_at: deliveredAt,
        updated_at: deliveredAt,
      },
    });
    // b) & c) Update all order items to 'delivered' status
    await tx.ecommerce_mall_order_items.updateMany({
      where: {
        id: {
          in: orderItemsToUpdate.map((item) => item.id),
        },
      },
      data: {
        status: "delivered",
        updated_at: deliveredAt,
      },
    });
    // d) Update order status based on all order items' statuses
    const orderIds = [
      ...new Set(
        orderItemsToUpdate.map((item) => item.ecommerce_mall_order_id),
      ),
    ];
    for (const orderId of orderIds) {
      const allOrderItems = await tx.ecommerce_mall_order_items.findMany({
        where: {
          ecommerce_mall_order_id: orderId,
          deleted_at: null,
        },
        select: {
          status: true,
        },
      });
      const statuses = allOrderItems.map((item) => item.status);
      const uniqueStatuses = [...new Set(statuses)];
      let newOrderStatus: string;
      if (uniqueStatuses.length === 1 && uniqueStatuses[0] === "delivered") {
        newOrderStatus = "delivered";
      } else {
        newOrderStatus = "partiallyCompleted";
      }
      await tx.ecommerce_mall_orders.update({
        where: { id: orderId },
        data: {
          status: newOrderStatus,
          updated_at: deliveredAt,
        },
      });
    }
  });
  // 6. Return updated shipment with order_items
  const updatedShipment =
    await MyGlobal.prisma.ecommerce_mall_shipments.findUnique({
      where: { id: props.shipmentId },
      select: {
        id: true,
        tracking_number: true,
        carrier_name: true,
        shipped_at: true,
        delivered_at: true,
        seller: {
          select: {
            id: true,
            email: true,
            shop_name: true,
            shop_description: true,
            approval_status: true,
            rejection_reason: true,
            account_status: true,
            created_at: true,
          },
        },
        created_at: true,
        updated_at: true,
        deleted_at: true,
      },
    });
  if (updatedShipment === null) {
    throw new HttpException("Shipment not found after update", 404);
  }
  // Get order items that were updated (from customer's orders)
  const shipmentOrderItems =
    await MyGlobal.prisma.ecommerce_mall_order_items.findMany({
      where: {
        ecommerce_mall_order_id: {
