  const cartItem =
    await MyGlobal.prisma.ecommerce_mall_cart_items.findUniqueOrThrow({
      where: {
        id: props.cartItemId,
        customer_id: props.customer.id,
        deleted_at: null,
      },
      select: {
        id: true,
        quantity: true,
        is_available: true,
        added_at: true,
        productVariant: {
          select: {
            id: true,
            sku_code: true,
            price: true,
            stock_quantity: true,
            deleted_at: true,
            product: {
              select: {
                id: true,
                name: true,
                base_price: true,
                status: true,
