    where: cursorInput ? { ...whereInput, AND: [cursorInput] } : whereInput,
    skip: props.body.cursor_added_at ? undefined : skip,
    take: limit + 1,
    orderBy: orderByInput,
    ...EcommerceMallCartItemAtSummaryTransformer.select(),
