import { TypedBody, TypedRoute } from "@nestia/core";
import { Controller, Ip } from "@nestjs/common";
import typia from "typia";

import { IEcommerceMallAdmin } from "../../../../api/structures/IEcommerceMallAdmin";
import { postEcommerceMallAuthAdminJoin } from "../../../../providers/postEcommerceMallAuthAdminJoin";
import { postEcommerceMallAuthAdminLogin } from "../../../../providers/postEcommerceMallAuthAdminLogin";
import { postEcommerceMallAuthAdminRefresh } from "../../../../providers/postEcommerceMallAuthAdminRefresh";

@Controller("/ecommerceMall/auth/admin")
export class EcommercemallAuthAdminController {
  /**
   * Administrator registration endpoint that creates a new admin account in the system. This operation validates the provided email address for format correctness and uniqueness, ensuring no duplicate administrator accounts exist. The password undergoes security validation to enforce minimum length and complexity requirements before being hashed using bcrypt with an appropriate cost factor for secure storage.
   *
   * Upon successful validation, a new admin record is created in the ecommerce_mall_admins table with the email address, hashed password, default admin_grade set to 'regular', and account_status set to 'active'. The system generates a unique UUID identifier for the admin account and records creation timestamps. The admin_grade field determines privilege levels, where 'regular' administrators can manage sellers, categories, products, orders, and users, while 'super' administrators have additional privileges for admin promotion/demotion.
   *
   * The response includes JWT access and refresh tokens for immediate authentication, along with the admin profile information. Account status validation ensures only 'active' accounts can authenticate, while 'suspended' or 'banned' accounts are rejected. Registration events are logged for security auditing and compliance purposes.
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Administrator registration credentials and profile information
   * @x-autobe-authorization-type join
   * @x-autobe-authorization-actor admin
   * @x-autobe-specification 1. Validate email format and uniqueness against ecommerce_mall_admins table
   * 2. Validate password meets security requirements (minimum length, complexity)
   * 3. Hash password using bcrypt with appropriate cost factor
   * 4. Create new admin record with email, password_hash, admin_grade='regular', account_status='active'
   * 5. Generate unique admin ID and set created_at/updated_at timestamps
   * 6. Return IAuthorized response with JWT access token, refresh token, and admin profile
   * 7. Log registration event for audit trail
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("join")
  public async join(
    @Ip()
    ip: string,
    @TypedBody()
    body: IEcommerceMallAdmin.IJoin,
  ): Promise<IEcommerceMallAdmin.IAuthorized> {
    try {
      return await postEcommerceMallAuthAdminJoin({
        ip,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Administrator login endpoint that authenticates admin credentials and establishes a secure session. This operation queries the ecommerce_mall_admins table using the provided email address to locate the administrator account. Account existence validation ensures only registered administrators can authenticate, while account_status verification confirms the account is in 'active' state, rejecting 'suspended' or 'banned' accounts.
   *
   * Password validation uses bcrypt comparison to verify the provided password matches the stored password_hash without exposing the actual password. Upon successful authentication, a session record is created in the ecommerce_mall_admin_sessions table containing connection metadata including client IP address, request URL (href), and HTTP referrer for security auditing and fraud detection. The session includes expiration timestamps for automatic invalidation.
   *
   * JWT access and refresh tokens are generated with claims containing admin ID, email address, and admin_grade for privilege-based authorization throughout the request lifecycle. Access tokens are short-lived for security, while refresh tokens enable seamless session renewal. The response includes both tokens along with the admin profile information, enabling immediate authenticated access to protected endpoints.
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Administrator login credentials
   * @x-autobe-authorization-type login
   * @x-autobe-authorization-actor admin
   * @x-autobe-specification 1. Query ecommerce_mall_admins table by email address
   * 2. Validate account exists and account_status is 'active'
   * 3. Verify password_hash matches provided password using bcrypt comparison
   * 4. Create session record in ecommerce_mall_admin_sessions with IP, href, referrer metadata
   * 5. Generate JWT access token with admin ID, email, admin_grade claims
   * 6. Generate refresh token linked to session ID
   * 7. Set token expiration based on session policy
   * 8. Return IAuthorized response with tokens and admin profile
   * 9. Log authentication event for security audit
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("login")
  public async login(
    @Ip()
    ip: string,
    @TypedBody()
    body: IEcommerceMallAdmin.ILogin,
  ): Promise<IEcommerceMallAdmin.IAuthorized> {
    try {
      return await postEcommerceMallAuthAdminLogin({
        ip,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Token refresh endpoint that renews expired JWT access tokens using a valid refresh token. This operation validates the refresh token's cryptographic signature and expiration timestamp to ensure it hasn't been tampered with or expired. The corresponding session is queried from the ecommerce_mall_admin_sessions table using the session ID embedded in the refresh token.
   *
   * Session validation confirms the session record exists, hasn't been soft-deleted (deleted_at is null), and hasn't expired (expired_at is in the future). The associated admin account is verified to still exist in the ecommerce_mall_admins table with an 'active' account_status, ensuring revoked or suspended accounts cannot renew tokens. This multi-layer validation prevents unauthorized access from compromised or expired sessions.
   *
   * Upon successful validation, a new JWT access token is generated with updated claims including the admin ID, email, and admin_grade. For enhanced security, the refresh token may be rotated, invalidating the old token and issuing a new one. The session's updated_at timestamp is refreshed to track activity. The response includes the new access token and refresh token, enabling continued authenticated access without requiring re-login.
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Refresh token for token renewal
   * @x-autobe-authorization-type refresh
   * @x-autobe-authorization-actor admin
   * @x-autobe-specification 1. Validate refresh token signature and expiration
   * 2. Query session from ecommerce_mall_admin_sessions by session ID
   * 3. Verify session exists and is not expired (expired_at > current time)
   * 4. Verify admin account still exists and account_status is 'active'
   * 5. Generate new JWT access token with updated claims
   * 6. Optionally rotate refresh token for enhanced security
   * 7. Update session updated_at timestamp
   * 8. Return IAuthorized response with new tokens
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("refresh")
  public async refresh(
    @TypedBody()
    body: IEcommerceMallAdmin.IRefresh,
  ): Promise<IEcommerceMallAdmin.IAuthorized> {
    try {
      return await postEcommerceMallAuthAdminRefresh({
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

