@Controller("/ecommerceMall/customer/wishlists")
export class EcommercemallCustomerWishlistsController {
  /**
   * Add a product to the authenticated customer's wishlist.
   *
   * This operation allows customers to save products they are interested in for future purchase. The product is linked to the customer's account and will appear in their wishlist until removed.
   *
   * The system validates that the product exists and is currently active (not deleted or suspended). Duplicate entries are prevented - if the product already exists in the customer's wishlist, the request will be rejected with a conflict error.
   *
   * Wishlist entries are automatically removed when the seller deletes the product. The system maintains a unique constraint on the combination of customer ID and product ID to ensure no duplicates.
   *
   * Related operations:
   * - GET /wishlists: View customer's wishlist with pagination
   * - DELETE /wishlists/{wishlistId}: Remove product from wishlist
   *
   * @param connection
   * @param body Product ID to add to wishlist
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor customer
   * @x-autobe-specification Create a wishlist entry linking customer to product.
   *
   * Implementation steps:
   * 1. Authenticate customer from session/token
   * 2. Validate product_id exists in ecommerce_mall_products table
   * 3. Verify product status is 'active' (not deleted/suspended)
   * 4. Check for existing wishlist entry (unique constraint on customer_id + product_id)
   * 5. If duplicate exists, return 409 Conflict
   * 6. Create wishlist record with:
   *    - ecommerce_mall_customer_id = authenticated customer ID
   *    - ecommerce_mall_product_id = request body product ID
   *    - active = true
   *    - deleted_at = null
   * 7. Return created wishlist entry with 201 Created
   *
   * Edge cases:
   * - Product deleted after addition: Application-level cascade removes wishlist entry
   * - Customer already has product in wishlist: Return 409 Conflict with duplicate error
   * - Product does not exist: Return 404 Not Found
   * - Customer not authenticated: Return 401 Unauthorized
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post()
  public async create(
    @CustomerAuth()
    customer: CustomerPayload,
    @TypedBody()
    body: IEcommerceMallWishlist.ICreate,
  ): Promise<IEcommerceMallWishlist> {
    try {
      return await postEcommerceMallCustomerWishlists({
        customer,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieve a filtered and paginated list of products saved to the customer's wishlist.
   *
   * This operation provides access to all products the customer has saved for future purchase. Each wishlist entry includes product details such as name, main image, current price, seller information, and stock availability status. Products are sorted by date added, with the newest items appearing first.
   *
   * The system automatically removes products from wishlists when sellers delete them, ensuring referential integrity. Deleted products will not appear in the wishlist listing. Out-of-stock products remain visible but are marked with their availability status.
   *
   * Pagination is supported to handle large wishlists efficiently. The response includes pagination metadata with total count, page size, and cursor information for navigation. Customers can only access their own wishlist; cross-access to other customers' wishlists is prohibited.
   *
   * Administrators may access customer wishlists for dispute resolution purposes through a separate administrative endpoint.
   *
   * @param connection
   * @param body Wishlist search criteria and pagination parameters
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor customer
   * @x-autobe-specification Query ecommerce_mall_wishlists table for the authenticated customer. Join with ecommerce_mall_products to retrieve product details including name, base_price, and status. Filter by active=true and deleted_at=null for wishlist entries. Exclude deleted products (deleted_at IS NOT NULL) as they are automatically removed per business rules. Apply pagination with cursor or offset-based pagination. Support sorting by created_at descending (newest first). Return wishlist entry summaries with product information including main image URI, name, base price or price range, stock availability status, and average rating if reviews exist. Implement referential integrity checks to ensure product references are valid. Handle cascade removal of deleted products from wishlists in the same transaction.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Patch()
  public async index(
    @CustomerAuth()
    customer: CustomerPayload,
    @TypedBody()
    body: IEcommerceMallWishlist.IRequest,
  ): Promise<IPageIEcommerceMallWishlist.ISummary> {
    try {
      return await patchEcommerceMallCustomerWishlists({
        customer,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieve a single wishlist entry with complete product information.
   *
   * This operation allows customers to view detailed information about a specific product saved in their wishlist. The wishlist entry represents one product saved by one customer, tracking when it was added and its active status for pagination and filtering. Products can be removed from the wishlist at any time, and deleted products are automatically removed via application logic or cascade.
   *
   * Access control is strictly enforced - only the customer who owns the wishlist entry can retrieve it, except for administrators who may access any wishlist item for support and dispute resolution purposes. The system automatically removes products from all customer wishlists when sellers delete those products, ensuring wishlist items always reference valid, active products. This is enforced through the composite unique constraint on [ecommerce_mall_customer_id, ecommerce_mall_product_id] which prevents duplicate entries.
   *
   * The response includes the product name, main image URL, current pricing, seller shop details, average customer rating, and real-time stock availability status. The wishlist entry includes the creation timestamp (created_at) indicating when the customer added the product to their wishlist, allowing customers to track their saved items chronologically. Product information is embedded directly in the response, eliminating the need for additional API calls to retrieve product details.
   *
   * The operation respects the soft-delete semantics where `deleted_at` marks when a wishlist entry was removed from the customer's visible wishlist while preserving the record for analytics purposes. Only entries where `active = true` and `deleted_at IS NULL` are returned.
   *
   * @param connection
   * @param wishlistId Unique identifier of the wishlist entry to retrieve (UUID format)
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor customer
   * @x-autobe-specification Retrieve a single wishlist entry by ID with full product details.
   *
   * 1. Validate authentication - customer must be logged in
   * 2. Query ecommerce_mall_wishlists table by id = {wishlistId}
   * 3. Verify ownership - wishlist.ecommerce_mall_customer_id must match authenticated customer ID, OR authenticated user must be administrator
   * 4. Check active status - only return if active = true and deleted_at IS NULL
   * 5. Join with ecommerce_mall_products to get product details
   * 6. Verify product exists and is not deleted (status != 'deleted' AND deleted_at IS NULL)
   * 7. Join with ecommerce_mall_sellers to get seller shop name
   * 8. Join with ecommerce_mall_product_images to get main thumbnail (is_primary = true OR sort_order = 0)
   * 9. Join with ecommerce_mall_reviews to calculate average rating for the product
   * 10. Check current stock status from ecommerce_mall_product_variants (sum of stock_quantity)
   * 11. Return IEcommerceMallWishlist with all embedded product information
   *
   * Error cases:
   * - 401: Not authenticated
   * - 403: Not the wishlist owner and not administrator
   * - 404: Wishlist entry not found or already deleted
   * - 404: Product has been deleted by seller
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Get(":wishlistId")
  public async at(
    @CustomerAuth()
    customer: CustomerPayload,
    @TypedParam("wishlistId")
    wishlistId: string & tags.Format<"uuid">,
  ): Promise<IEcommerceMallWishlist> {
    try {
      return await getEcommerceMallCustomerWishlistsWishlistId({
        customer,
        wishlistId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Update an existing customer wishlist entry with modified information.
   *
   * This operation allows authenticated customers to modify their own wishlist entries, primarily to control the visibility status of saved products. Customers can mark wishlist items as inactive to hide them from their active wishlist display, or reactivate previously hidden items. The operation updates the `active` boolean field and synchronizes the `deleted_at` timestamp accordingly.
   *
   * **Security and Authorization**:
   *
   * Only the owning customer can update their wishlist entries. The system validates that the authenticated customer (from JWT token) owns the specified wishlist entry by verifying the `ecommerce_mall_customer_id` field matches the authenticated customer's ID. Administrators cannot directly modify customer wishlists per platform policy. Attempting to update another customer's wishlist entry returns a 403 Forbidden response.
   *
   * **Database Schema Relationship**:
   *
   * The operation updates the `ecommerce_mall_wishlists` table, which stores the many-to-many relationship between customers (`ecommerce_mall_customer_id`) and products (`ecommerce_mall_product_id`). Each wishlist entry includes creation timestamp (`created_at`), update timestamp (`updated_at`), soft deletion timestamp (`deleted_at`), and active status (`active`). The unique constraint on `[ecommerce_mall_customer_id, ecommerce_mall_product_id]` ensures customers cannot have duplicate wishlist entries for the same product.
   *
   * **Update Behavior and Validation**:
   *
   * Setting `active` to `false` marks the entry as inactive and populates `deleted_at` with the current timestamp, effectively hiding it from the customer's active wishlist display. Setting `active` to `true` reactivates the entry and clears `deleted_at`. The `updated_at` field is automatically set to the current timestamp on every update. Invalid request body schemas return a 400 Bad Request response.
   *
   * **Automatic Cascade Removal**:
   *
   * If the associated product is deleted by its seller, the system automatically removes the wishlist entry via database cascade (`onDelete: Cascade` on `ecommerce_mall_product_id`). This occurs within the same transaction as the product deletion and does not require explicit customer action. Similarly, if a customer account is deleted, all their wishlist entries are automatically removed.
   *
   * **Related Operations**:
   *
   * - `PATCH /ecommerceMall/customer/wishlists` - List customer's wishlist entries with pagination and filtering
   * - `POST /ecommerceMall/customer/wishlists` - Add a new product to the customer's wishlist
   * - `DELETE /ecommerceMall/customer/wishlists/{wishlistId}` - Permanently remove a wishlist entry
   *
   * @param connection
   * @param wishlistId Target wishlist entry's unique identifier (UUID format)
   * @param body Update information for the wishlist entry, primarily the active status field
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor customer
   * @x-autobe-specification Implement update operation for ecommerce_mall_wishlists table:
   *
   * 1. **Authentication and Authorization**:
   *    - Validate JWT token and extract customer ID
   *    - Query wishlist entry by {wishlistId}
   *    - Verify ecommerce_mall_customer_id matches authenticated customer
   *    - Return 404 if entry not found or 403 if not owned
   *
   * 2. **Update Validation**:
   *    - Validate request body schema (IEcommerceMallWishlist.IUpdate)
   *    - If 'active' field provided, ensure it's a boolean
   *    - If 'active' is false, ensure deleted_at is set to current timestamp
   *    - If 'active' is true, ensure deleted_at is null
   *
   * 3. **Database Update**:
   *    - Begin transaction
   *    - Update wishlist entry with provided fields
   *    - Set updated_at to current timestamp
   *    - Commit transaction
   *
   * 4. **Response**:
   *    - Return 200 with updated IEcommerceMallWishlist object
   *    - Include all fields: id, ecommerce_mall_customer_id, ecommerce_mall_product_id, created_at, updated_at, deleted_at, active
   *
   * 5. **Error Handling**:
   *    - 401: Unauthorized (invalid/missing JWT)
   *    - 403: Forbidden (customer does not own this wishlist entry)
   *    - 404: Not Found (wishlist entry does not exist)
   *    - 400: Bad Request (invalid request body schema)
   *    - 500: Internal Server Error (database transaction failure)
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
